export type IconName = keyof typeof ICONS

export function Icon({ name, size = 14, color = 'currentColor', style }: { name: IconName; size?: number; color?: string; style?: CSSProperties }) {
  const def = ICONS[name]
  return (
    <svg width={size} height={size} viewBox={def.vb} fill="none" style={{ display: 'block', flexShrink: 0, ...style }}>
      {def.d.map((d, i) => (
        <path key={i} d={d} fill={color} />
      ))}
    </svg>
  )
}

